// ─── MAP FORM TO ROW FORMAT ──────────────────────────────────────────────────
const fs = require('fs');

const configPath  = '/data/wallpaper/config.json';
const stylesPath  = '/data/wallpaper/styles.json';
const socialPath  = '/data/wallpaper/social.json';

const config  = JSON.parse(fs.readFileSync(configPath,  'utf8'));
const styles  = JSON.parse(fs.readFileSync(stylesPath,  'utf8'));
const social  = JSON.parse(fs.readFileSync(socialPath,  'utf8'));

const form = $input.first().json;

const row = {
  project_name:   form['Project Name']            || 'Untitled',
  theme:          form['Theme / Description']      || '',
  style:          form['Style']                    || 'Cinematic',
  'Use Case':     form['Use Case']                 || 'wallpaper',
  count:          form['How many images?']         || '4',
  prompt_add:     form['Extra details (optional)'] || '',
  mood:           form['Mood (optional)']          || '',
  color_palette:  form['Colors (optional)']        || '',
  model:          '',
  steps:          '',
  cfg_scale:      '',
  negative_prompt:'',
  custom_prompt:  ''
};

const cleanStyles = {};
Object.keys(styles).forEach(k => { if (!k.startsWith('_')) cleanStyles[k] = styles[k]; });

return [{ json: { row, config, styles: cleanStyles, social, csvPath: null, header: [] } }];

// Same Ollama enrichment as batch workflow
const row    = $json.row;
const config = $json.config;
const styles = $json.styles;
const social = $json.social;

const useCase = (row['Use Case'] || 'wallpaper').toLowerCase();
const useCaseAura = {
  wallpaper: 'seamless full-bleed background, no UI elements, immersive environment',
  poster:    'studio product photography, strong focal point, premium ad quality',
  sticker:   'isolated subject on transparent/solid background, bold clean edges, cartoon-friendly',
  frame:     'ornate decorative border, baroque or luxury frame style, elegant inner space'
};
const aura   = useCaseAura[useCase] || useCaseAura.wallpaper;
const styleKey = row.style || 'Cinematic';
const preset   = styles[styleKey] || styles['Cinematic'];

const systemPrompt = `You are an expert AI art director. Respond ONLY with a JSON object, no markdown, no explanation.
Required keys: main_prompt, negative_prompt, title, description, tags (array 10), mood, color_palette, subject_details`;

const userPrompt = `Project: ${row.project_name}\nTheme: ${row.theme}\nStyle: ${styleKey}\nUse Case: ${useCase} — ${aura}\nMood: ${row.mood || ''}\nColors: ${row.color_palette || ''}\nExtra: ${row.prompt_add || ''}\nStyle prefix: ${preset.prompt_prefix}\nStyle suffix: ${preset.prompt_suffix}\nMake a vivid SDXL-optimised prompt. 9:16 vertical composition. Include #momentlabs in tags.`;

const ollamaUrl = config.ollama_url || 'http://host.docker.internal:11434';
const model     = config.ollama_model || 'qwen3:8b';

const response = await fetch(`${ollamaUrl}/api/chat`, {
  method: 'POST',
  headers: { 'Content-Type': 'application/json' },
  body: JSON.stringify({
    model,
    messages: [{ role: 'system', content: systemPrompt }, { role: 'user', content: userPrompt }],
    stream: false,
    options: { temperature: 0.8, num_predict: 600 }
  })
});

if (!response.ok) throw new Error(`Ollama error: ${response.status}`);
const data = await response.json();
let enriched;
try {
  const raw = data.message?.content || data.response || '{}';
  const m = raw.match(/\{[\s\S]*\}/);
  enriched = JSON.parse(m ? m[0] : raw);
} catch(e) {
  enriched = { main_prompt: `${preset.prompt_prefix}, ${row.theme}, ${preset.prompt_suffix}`, negative_prompt: preset.negative_prompt, title: row.project_name, description: row.theme, tags: ['#momentlabs'], mood: row.mood, color_palette: row.color_palette, subject_details: row.theme };
}

const count = parseInt(row.count) || 4;
const steps = parseInt(row.steps) || preset.steps || config.default_steps || 25;
const cfg   = parseFloat(row.cfg_scale) || preset.cfg || config.default_cfg || 7.5;

return [{ json: { ...$json, enriched, useCase, count, model: row.model || config.default_model || 'realvis', steps, cfg, preset } }];

// Same ComfyUI submit as batch
const config   = $json.config;
const enriched = $json.enriched;
const row      = $json.row;
const models   = config.models || {};
const modelFile = models[$json.model] || models['realvis'] || 'realvisxlV50_v50Bakedvae.safetensors';
const width = config.image?.width || 1080, height = config.image?.height || 1920;
const count = $json.count || 4, steps = $json.steps || 25, cfg = $json.cfg || 7.5;

const workflow = {
  "1": { "class_type": "CheckpointLoaderSimple", "inputs": { "ckpt_name": modelFile } },
  "2": { "class_type": "CLIPTextEncode", "inputs": { "text": enriched.main_prompt, "clip": ["1", 1] } },
  "3": { "class_type": "CLIPTextEncode", "inputs": { "text": enriched.negative_prompt || 'watermark, text, blur', "clip": ["1", 1] } },
  "4": { "class_type": "EmptyLatentImage", "inputs": { "width": width, "height": height, "batch_size": count } },
  "5": { "class_type": "KSampler", "inputs": { "model": ["1", 0], "positive": ["2", 0], "negative": ["3", 0], "latent_image": ["4", 0], "seed": Math.floor(Math.random()*9999999999), "steps": steps, "cfg": cfg, "sampler_name": $json.preset?.sampler || "euler_ancestral", "scheduler": "karras", "denoise": 1.0 } },
  "6": { "class_type": "VAEDecode", "inputs": { "samples": ["5", 0], "vae": ["1", 2] } },
  "7": { "class_type": "SaveImage", "inputs": { "images": ["6", 0], "filename_prefix": `ml_instant_${row.project_name.replace(/\s+/g,'_').toLowerCase()}` } }
};

const comfyUrl = config.comfyui_url || 'http://host.docker.internal:8188';
const res = await fetch(`${comfyUrl}/prompt`, { method:'POST', headers:{'Content-Type':'application/json'}, body: JSON.stringify({ prompt: workflow, client_id: 'moment_labs_instant' }) });
if (!res.ok) throw new Error(`ComfyUI error: ${res.status}`);
const d = await res.json();
if (!d.prompt_id) throw new Error('No prompt_id');

return [{ json: { ...$json, promptId: d.prompt_id, comfyUrl, width, height, count } }];

