https.get(url,res=>{let d='';res.on('data',c=>d+=c);res.on('end',()=>{try{const h=JSON.parse(d),e=h['{{ $json.promptId }}'];if(e&&e.status&&e.status.completed){const imgs=[];Object.values(e.outputs).forEach(o=>{if(o.images)o.images.forEach(i=>imgs.push(i));});console.log(JSON.stringify({done:true,images:imgs}));}else{setTimeout(()=>poll(n+1),wait);}}catch(e){setTimeout(()=>poll(n+1),wait);}});}).on('error',()=>setTimeout(()=>poll(n+1),wait));}
poll(1);
"

