// Download images + write meta.json
const fs = require('fs'), path = require('path'), http = require('http');
const stdout = $json.stdout || '{}';
let pr;
try { pr = JSON.parse(stdout.trim().split('\n').pop()); } catch(e) { throw new Error('Poll parse fail: '+stdout); }
if (!pr.done) throw new Error('ComfyUI timeout');

const row=$json.row, enriched=$json.enriched, config=$json.config, social=$json.social;
const safeP = row.project_name.replace(/[^a-zA-Z0-9_\-]/g,'_');
const ts = new Date().toISOString().split('T')[0];
const outFolder = path.join(config.output_folder, `${ts}_${safeP}_instant`);
if(!fs.existsSync(outFolder)) fs.mkdirSync(outFolder, {recursive:true});

const comfyBase = config.comfyui_url || 'http://host.docker.internal:8188';
const savedFiles = [];

for(let i=0;i<(pr.images||[]).length;i++){
  const img=pr.images[i];
  const fname=`${safeP}_${String(i+1).padStart(2,'0')}.png`;
  const fpath=path.join(outFolder,fname);
  const dlUrl=`${comfyBase}/view?filename=${img.filename}&type=${img.type}&subfolder=${img.subfolder||''}`;
  await new Promise((res,rej)=>{ const f=fs.createWriteStream(fpath); http.get(dlUrl,r=>{r.pipe(f);f.on('finish',()=>{f.close();res();});}).on('error',e=>{fs.unlinkSync(fpath);rej(e);}); });
  savedFiles.push({filename:fname,path:fpath});
}

const meta = { project_name:row.project_name, use_case:$json.useCase, style:row.style, date:new Date().toISOString(), title:enriched.title, description:enriched.description, tags:enriched.tags, mood:enriched.mood, color_palette:enriched.color_palette, subject_details:enriched.subject_details, main_prompt:enriched.main_prompt, negative_prompt:enriched.negative_prompt, model:$json.model, steps:$json.steps, cfg:$json.cfg, image_count:savedFiles.length, images:savedFiles.map(f=>f.filename), instagram:social.instagram_handle };
fs.writeFileSync(path.join(outFolder,'meta.json'), JSON.stringify(meta,null,2));

try { await fetch('http://localhost:5679/webhook/automate-job-log',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({workflow:'Moment.Labs Instant',status:'success',details:`${row.project_name} — ${savedFiles.length} images`})}); } catch(e){}

return [{ json: { success:true, project:row.project_name, images:savedFiles.length, folder:outFolder, meta } }];
